// I007/450 - Directed Interrogation Result
// Compound data item with FX-extensible primary subfield.
// Subfield #1: Truncation (1 octet)
// Subfield #2: Mode 4 Interrogations (1 octet)
// Subfield #3: Mode 5 Interrogations (1 octet)
// Subfield #4: Mode S All Call Interrogations (2 octets)
// Subfield #5: Mark X Interrogations (1 octet)
// Subfield #6: Selective Mode S Interrogations (1 octet)
class Cat007I450 {
public:
    const Cat007I450sub& sub() const { return sub_; }
    Cat007I450sub& mutable_sub() { return sub_; }
    void set_sub(const Cat007I450sub& v) { sub_ = v; }

    bool operator==(const Cat007I450&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        CONDUIT_TRY(sub_.encode(w));
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007I450> decode(conduit::io::BitReader& r) {
        Cat007I450 result;
        {
            auto val = Cat007I450sub::decode(r);
            if (!val) return std::unexpected(val.error());
            result.sub_ = std::move(*val);
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat007I450{"
            << "sub=" << sub_.to_string()
            << "}";
        return oss.str();
    }

private:
    Cat007I450sub sub_{};
};

