    const uint8_t& saa() const { return saa_.value(); }
    uint8_t& mutable_saa() { if (!saa_) saa_.emplace(); return *saa_; }
    void set_saa(const uint8_t& v) { saa_ = v; }
    void clear_saa() { saa_.reset(); }

