class Cat021I220sub {
public:
    bool has_ws() const { return ws_.has_value(); }
    const Cat021I220Ws& ws() const { return ws_.value(); }
    Cat021I220Ws& mutable_ws() { if (!ws_) ws_.emplace(); return *ws_; }
    void set_ws(const Cat021I220Ws& v) { ws_ = v; }
    void clear_ws() { ws_.reset(); }

    bool has_wd() const { return wd_.has_value(); }
    const Cat021I220Wd& wd() const { return wd_.value(); }
    Cat021I220Wd& mutable_wd() { if (!wd_) wd_.emplace(); return *wd_; }
    void set_wd(const Cat021I220Wd& v) { wd_ = v; }
    void clear_wd() { wd_.reset(); }

    bool has_tmp() const { return tmp_.has_value(); }
    const Cat021I220Tmp& tmp() const { return tmp_.value(); }
    Cat021I220Tmp& mutable_tmp() { if (!tmp_) tmp_.emplace(); return *tmp_; }
    void set_tmp(const Cat021I220Tmp& v) { tmp_ = v; }
    void clear_tmp() { tmp_.reset(); }

    bool has_trb() const { return trb_.has_value(); }
    const uint8& trb() const { return trb_.value(); }
    uint8& mutable_trb() { if (!trb_) trb_.emplace(); return *trb_; }
    void set_trb(const uint8& v) { trb_ = v; }
    void clear_trb() { trb_.reset(); }

    bool operator==(const Cat021I220sub&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (ws_.has_value() && 0 > last_octet) last_octet = 0;
        if (wd_.has_value() && 0 > last_octet) last_octet = 0;
        if (tmp_.has_value() && 0 > last_octet) last_octet = 0;
        if (trb_.has_value() && 0 > last_octet) last_octet = 0;
        std::array<uint8_t, 1> fspec{};
        if (ws_.has_value()) fspec[0] |= (1 << 7);
        if (wd_.has_value()) fspec[0] |= (1 << 6);
        if (tmp_.has_value()) fspec[0] |= (1 << 5);
        if (trb_.has_value()) fspec[0] |= (1 << 4);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (ws_.has_value()) {
            CONDUIT_TRY(ws_->encode(w));
        }
        if (wd_.has_value()) {
            CONDUIT_TRY(wd_->encode(w));
        }
        if (tmp_.has_value()) {
            CONDUIT_TRY(tmp_->encode(w));
        }
        if (trb_.has_value()) {
            w.write_bits(*trb_, 8);
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat021I220sub> decode(conduit::io::BitReader& r) {
        Cat021I220sub result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 1) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = Cat021I220Ws::decode(r);
            if (!val) return std::unexpected(val.error());
            result.ws_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = Cat021I220Wd::decode(r);
            if (!val) return std::unexpected(val.error());
            result.wd_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 5))) {
            auto val = Cat021I220Tmp::decode(r);
            if (!val) return std::unexpected(val.error());
            result.tmp_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 4))) {
            auto val = r.read_bits(8);
            if (!val) return std::unexpected(val.error());
            result.trb_ = static_cast<uint8>(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat021I220sub{";
        bool first = true;
        if (ws_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "ws=" << (*ws_).to_string();
        }
        if (wd_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "wd=" << (*wd_).to_string();
        }
        if (tmp_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "tmp=" << (*tmp_).to_string();
        }
        if (trb_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "trb=" << static_cast<uint64_t>(*trb_);
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<Cat021I220Ws> ws_;
    std::optional<Cat021I220Wd> wd_;
    std::optional<Cat021I220Tmp> tmp_;
    std::optional<uint8> trb_;
};

